"""Derived presentation tables only: accepted fits plus accepted resolution metadata."""
from pathlib import Path
import argparse,json,hashlib
import pandas as pd
from new_adapter import path,sha

def main():
 p=argparse.ArgumentParser();p.add_argument('--output',required=True);a=p.parse_args();out=path(a.output);assert not out.exists()
 src=path('analysis/cycle07_newsource_empirical_baseline_v1');receipt=src/'run_receipt.json';pins={str(Path(__file__)):sha(Path(__file__))}
 for name in ['audit.json','spatial_audit.json']:
  q=path('reviews/cycle07_newsource_empirical_regression_independent')/name;ad=json.loads(q.read_text());assert ad['all_checks_passed']is True and sha(receipt)in q.read_text();pins[str(q)]=sha(q)
 registry=path('model/cycle07_scale_hierarchy/empirical_registry_source477_v1/registry_receipt.json');review=path('reviews/cycle07_empirical_registry_independent/audit.json');table=registry.parent/'empirical_level_registry.csv';r=json.loads(registry.read_text());assert json.loads(review.read_text())['all_checks_passed']is True and sha(registry)in review.read_text();assert sha(table)==r['files'][table.name];mapping=pd.read_csv(table).set_index('candidate_cap').empirical_level.to_dict()
 for q in [receipt,src/'model_metrics.csv',src/'sample_gates.csv',src/'spatial_residual_diagnostics.csv',registry,review,table]:pins[str(q)]=sha(q)
 d=pd.read_csv(src/'model_metrics.csv');g=pd.read_csv(src/'sample_gates.csv');assert set(d.candidate_cap)==set(mapping);d['admitted_empirical_level']=d.candidate_cap.map(mapping);g['admitted_empirical_level']=g.candidate_cap.map(mapping)
 z=d[d.scenario.str.endswith('__primary')|d.scenario.str.endswith('__rural_population_sensitivity')].sort_values(['admitted_empirical_level','scenario','model']);assert len(z)==40
 text=['Четыре вложенных разбиения взяты из независимо принятого эмпирического реестра. Индексы 0–3 описывают разрешение разбиения; транспортные пределы 45/60/90/120 минут сами по себе не являются заранее заданными географическими уровнями. Пять сценариев конечного леса относятся к другой семье результатов.', '', '| Уровень / предел | Семейство | n / регионов | R² всей зоны: M1 → M2 → M3 | R² сельской части: M1 → M2 → M3 |','|---|:---|---:|:---|:---|']
 for cap,level in sorted(mapping.items(),key=lambda x:x[1]):
  for family in ['A_M1_M2','B_M1_M2_M3_inventory']:
   whole=z[(z.candidate_cap==cap)&(z.scenario==family+'__primary')].sort_values('model');rural=z[(z.candidate_cap==cap)&(z.scenario==family+'__rural_population_sensitivity')].sort_values('model');assert whole.n.nunique()==rural.n.nunique()==1 and whole.n.iloc[0]==rural.n.iloc[0];fmt=lambda q:' → '.join(f'{x:.4f}'for x in q.group_oof_r2_train_mean_baseline)
   text.append(f'| {level} / {cap} мин | {family[0]} | {int(whole.n.iloc[0])} / {int(whole.regions.iloc[0])} | {fmt(whole)} | {fmt(rural)} |')
 text+=['', 'В семействе B на уровне 0 добавление инвентарного блока ухудшает качество всей зоны на отложенных регионах, но улучшает сельский исход. На уровнях 1–3 сельский исход также выигрывает от M3; величина выигрыша и выборки различаются. Это не доказывает причинный эффект или функциональную полицентричность. Семейства A/B нельзя сравнивать как один последовательный эксперимент: у них разные общие выборки.', '', 'Максимальная дистанция Кука первичной модели A_M1 уровня 0 превышает 12: процентный исход чувствителен к малой исходной базе и влиятельным наблюдениям. Наблюдения не исключались; разбиения и пороги не выбирались по качеству регрессии. Масса центра 2021 фиксирована относительно назначения районов, но не является временно экзогенной причиной демографической динамики 2010–2021.', '', 'Чисто первичные и поддержанные первичные чувствительности 2010 во всех четырёх разбиениях не проходят заранее заданные ограничения размера выборки или числа регионов. Национальная верификация на исключительно первичных значениях 2010 поэтому не получена. Основные результаты условны на опубликованных и защищённых вторичных значениях; неизменность границ не доказана.', '', 'Контексты сельской зоны взвешены населением 2010 при полном объявленном аддитивном исходном составе. Из сельской зоны исключено ровно одно ядро; известный ноль сохранён, неизвестные значения не заменялись нулями. Сельская чувствительность использует ту же общую выборку соответствующего семейства. Время к ядру отдельно от времени к крупному городу; последнее ограничено 180 минутами, за пределом поля остаётся неизвестным.', '', 'FAO-почвенный индекс — прокси низкозатратной кукурузы, не российский бонитет. Инвентарные HHI и числа исходных поставщиков не измеряют мощности или доказанную полицентричность. Остаточная пространственная зависимость сохраняется: OOF Moran p=0.006 для уровня 0 и p=0.002 для остальных первичных моделей; диагностическая точечная KNN-сеть не является исправлением зависимости.', '', 'Численные результаты и пространственные диагностики независимо проверены. Статус рисунков определяется отдельной квитанцией визуальной и скалярной приёмки.']
 out.mkdir(parents=True);d.to_csv(out/'all_reviewed_model_metrics_with_level_metadata.csv',index=False);g.to_csv(out/'all_reviewed_sample_gates_with_level_metadata.csv',index=False);z.to_csv(out/'whole_and_rural_heldout_validation.csv',index=False);(out/'interpretation_ru.md').write_text('\n'.join(text)+'\n')
 for q,h in pins.items():assert sha(Path(q))==h
 rec={'status':'DERIVED_PRESENTATION_NO_REFIT_NO_SOURCE_RECLASSIFICATION','n_fits':len(d),'n_primary_and_rural_rows':len(z),'empirical_level_by_cap':mapping,'inputs_sha256':pins,'outputs_sha256':{q.name:sha(q)for q in out.iterdir()}};(out/'receipt.json').write_text(json.dumps(rec,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'receipt_sha256':sha(out/'receipt.json')}))
if __name__=='__main__':main()
